create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_SALES_VARIANT (
	SALES_VARIANT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for an sales variant of a product.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	SALES_VARIANT_NR VARCHAR(20) COMMENT 'The number by which the sales variant is known to business.',
	GTIN VARCHAR(14) COMMENT 'The Global Trade Item Number (GTIN) that identifies this item variant.',
	SALES_VARIANT_NAME VARCHAR(500) NOT NULL COMMENT 'The name of the product variant.',
	PROD_VARIANT_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'A code that defines the lifecycle status of the sales variant,',
	PROD_VARIANT_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the status code of a product variant in group language, i.e. in German.',
	SALES_VARIANT_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for sales variants.',
	SALES_VARIANT_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminator for sales variants. (Description in group language, i.e. in German)',
	WEIGHT_BASED_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product variant is sold by weight instead of count.',
	SALES_VARIANT_CONTENT_MEAS NUMBER(38,5) COMMENT 'The content or size of the sales variant. E.g. 750ml. In case the sales variant consists of several units (e.g. 6 bottles with 1 liter each), this is the total content (i.e. 6 liters in this example). For weight-based products, this attribute is empty.',
	UNIT_CNT NUMBER(38,0) COMMENT 'In case the sales variant consists of several units, this is the number of units, which are contained in the sales variant. E.g. for a pack of 6 bottles this is 6. For weight-based products, this attribute is empty.',
	UNIT_CONTENT_MEAS NUMBER(38,5) COMMENT 'In case the sales variant consists of several units, this is the content or size of a single unit. E.g. for a pack of 6 bottles of 1 liter each, this is 1 liter. For weight-based products, this attribute is empty.',
	CONTENT_UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit of measure, such as kg, meter or pieces.',
	NON_FOOD_VARIANT_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for non food variants.',
	NON_FOOD_VARIANT_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminator for non food variants. (Description in group language, i.e. in German)',
	SIZE_NAME VARCHAR(500) COMMENT 'The name for the size of the sales variant. E.g. small / medium / large.',
	STYLE_NAME VARCHAR(500) COMMENT 'The name for the style of the sales variant, e.g. the color.',
	KIND_NAME VARCHAR(500) COMMENT 'The name of the local variation of the product, e.g. for the kind of plug (European vs. UK vs. US style of plugs) or of the kind of fruits or vegetables.',
	FRUITS_AND_VEGETABLES_CLASS_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the(quality) class for fruits and vegetables.',
	FRUITS_AND_VEGETABLES_CLASS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the (quality) class for fruits and vegetables. (Description in group language, i.e. in German)',
	MIN_CALIBER_MEAS NUMBER(38,5) COMMENT 'The minimum size (in the indicated unit of measure) for this caliber.',
	MAX_CALIBER_MEAS NUMBER(38,5) COMMENT 'The maximum size (in the indicated unit of measure) for this caliber.',
	CALIBER_UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit of measure for the caliber.',
	COUNTRY_OF_ORIGIN_CD VARCHAR(2) NOT NULL COMMENT 'The code identifying the country of origin of the sales variant, according to ISO 3166.',
	COUNTRY_OF_ORIGIN_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the country of origin of this sales variant.',
	PROD_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product, which is the base for this sales variant.',
	PROD_NR VARCHAR(20) COMMENT 'The number which (globally) identifies the product which is the base for this sales variant, within the organization. (Note that the product number is unique for a certain point in time, but may be re-used later on.)',
	PROD_NAME VARCHAR(250) NOT NULL COMMENT 'The name of the global product, which is the base for this sales variant.',
	ITEM_FAM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related item family, which contains this sales variant.',
	ITEM_FAM_NR VARCHAR(100) COMMENT 'The number by which the related item family is known to business.',
	ITEM_FAM_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the item related family in group language, i.e. in German.',
	SUB_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the sub item group, which contains this sales variant.',
	SUB_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related sub item group is known to business.',
	SUB_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related sub item group in group language, i.e. in German.',
	INT_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the international item group, which contains this sales variant.',
	INT_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related international item group is known to business.',
	INT_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related international item group in group language, i.e. in German.',
	PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the pillar, which contains this sales variant.',
	PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related pillar is known to business.',
	PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related pillar in group language, i.e. in German.',
	MAIN_PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the main pillar, which contains this sales variant.',
	MAIN_PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related main pillar is known to business.',
	MAIN_PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related main pillar in group language, i.e. in German.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_SALES_VARIANT primary key (SALES_VARIANT_SID, DWH_VALID_FROM_TMSP)
)COMMENT='The sales variants describes the kind of individual product, which is offered for sale. Variants of the same product may differ in their size (e.g. small, medium and large t-shirts), colour, style, flavour (e.g. strawberry and cherry yoghurt) or in certain technical details, such as a UK plug for a toaster.'
;